<?php
require_once __DIR__.'/includes/functions.php';require_login();$errors=[];$user=current_user();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$phone=trim($_POST['phone']??'');$address=trim($_POST['address']??'');$locality=trim($_POST['locality']??'');if($name===''||mb_strlen($name)>120)$errors[]='Enter a name up to 120 characters.';if(mb_strlen($phone)>30||mb_strlen($address)>255||mb_strlen($locality)>120)$errors[]='One or more profile fields are too long.';if(!$errors){$q=$pdo->prepare('UPDATE users SET name=?,phone=?,address=?,locality=? WHERE id=?');$q->execute([$name,$phone,$address,$locality,$user['id']]);$_SESSION['user']=array_merge($user,['name'=>$name,'phone'=>$phone,'address'=>$address,'locality'=>$locality]);flash('success','Your profile has been updated.');redirect('profile.php');}}
$page_title='My profile | SharePlate';require __DIR__.'/includes/header.php';?>
<section class="form-section"><div class="form-card"><p class="eyebrow">Your account</p><h1>Profile details</h1><p class="muted">Signed in as <?=e($user['email'])?> · <?=e(ucfirst($user['role']))?></p><?php foreach($errors as $error):?><div class="alert alert-error"><?=e($error)?></div><?php endforeach;?><form method="post" class="stack-form"><?=csrf_field()?><label>Name<input required name="name" maxlength="120" value="<?=e($_POST['name']??$user['name'])?>"></label><label>Phone<input name="phone" maxlength="30" value="<?=e($_POST['phone']??$user['phone'])?>"></label><label>Address<input name="address" maxlength="255" value="<?=e($_POST['address']??$user['address'])?>"></label><label>City or locality<input name="locality" maxlength="120" value="<?=e($_POST['locality']??$user['locality'])?>"></label><button class="button">Save profile</button></form></div></section><?php require __DIR__.'/includes/footer.php';?>